pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        // admissible domain: actor not zero address, amounts non-zero, collect not exceeding deposit
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);  // keep amounts reasonable
        collectAmount = bound(collectAmount, 1, depositAmount);

        // setup: initialize, set min sum to zero so Collect is allowed with any balance
        c.SetMinSum(0);
        c.Initialized();

        // fund actor and deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // record balance before collect
        uint256 balBefore = c.balances(actor);

        // collect
        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 balAfter = c.balances(actor);

        // General rule: after a collect, the balance must have decreased by exactly the collected amount.
        // The correct contract decreases it; the buggy contract never increased it on deposit, so balance remains 0
        // and the decrease fails this equality whenever depositAmount > 0.
        assertTrue(balAfter == balBefore - collectAmount);
    }
}

