contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address depositor, address collector) public {
        // Bound amounts to reasonable range to avoid overflow in addition checks and ensure positivity
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= 1e36);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= 1e36);

        // Ensure distinct actors to isolate balance changes
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));
        vm.assume(depositor != collector);

        // Initialize contract
        vm.prank(address(this));
        c.Initialized();

        // Setup: depositor deposits Ether
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Record balance before attempt
        uint256 balanceBefore = c.balances(depositor);

        // Collector attempts to collect, but collector has no balance so Collect will not execute
        // and depositor's balance should be unchanged regardless of bug.
        // To test the property, we need a scenario where depositor's balance could be affected.
        // We instead let depositor collect their own balance.
        // First, record depositor's balance after deposit.
        // Then depositor attempts to collect a part of it.
        vm.prank(depositor);
        // Ensure collectAmount <= balanceBefore to allow successful collect in reference
        vm.assume(collectAmount <= balanceBefore);
        try c.Collect(collectAmount) {} catch {}

        // After collect, in reference, depositor's balance = balanceBefore - collectAmount.
        // In buggy version, Deposit set balance to 0, so Collect may revert or result in 0.
        // The property: depositor's balance never becomes strictly less than balanceBefore - collectAmount.
        // More precisely, the balance after the sequence must be at least balanceBefore - collectAmount.
        // In reference, equality holds; in buggy, balance will be 0 (if deposit was bugged) which is less.
        uint256 balanceAfter = c.balances(depositor);
        assertTrue(balanceAfter >= balanceBefore - collectAmount);
    }
}

