contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 minSum1, uint256 minSum2, uint256 amt) public {
        // keep values reasonable to avoid overflow needing massive ether
        vm.assume(minSum1 != minSum2);
        vm.assume(minSum1 > 0 && minSum2 > 0);
        vm.assume(amt > 0 && amt < type(uint256).max / 2);

        // initialization sequence: set log, set minSum1, initialize
        c.SetLogFile(address(new LogFile()));
        c.SetMinSum(minSum1);
        c.Initialized();

        // Attempt to change MinSum again (bug allows it, reference ignores)
        c.SetMinSum(minSum2);

        // Provide actor with enough balance to meet both minSum1 and amt
        uint256 depositAmount = amt;
        if (depositAmount < minSum1) depositAmount = minSum1;
