        depositAmount = depositAmount + 1; // ensure strictly greater than both minSums

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Perform the Collect that exposes the difference
        vm.prank(actor);
        c.Collect(amt);

        // After Collect, MinSum should still be the originally initialized minSum1 in the reference
        // but the bug may have changed it to minSum2.
        // Reference invariant: MinSum never changes after initialization.
        assertTrue(c.MinSum() == minSum1);
    }
}

