pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 depositAmt, uint256 collectAmt, uint256 newMinSum) public {
        // Keep minSum within reasonable bounds and > 0 so balances can reach it
        vm.assume(minSum > 0);
        vm.assume(minSum < type(uint256).max / 2);
        // depositAmt must be >= minSum so that Collect can succeed
        vm.assume(depositAmt >= minSum);
        vm.assume(depositAmt < type(uint256).max / 2);
        // collectAmt must not exceed depositAmt
        vm.assume(collectAmt <= depositAmt);
        vm.assume(collectAmt > 0);

        // Initialize the reference contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Record the expected immutable MinSum after initialization
        uint256 expectedMinSum = c.MinSum();

        // Try to change MinSum after initialization (this will succeed only in the buggy version)
        address caller = address(0x1234);
        vm.prank(caller);
        c.SetMinSum(newMinSum);

        // Deposit funds so Collect can succeed
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Now trigger Collect
        vm.prank(caller);
        c.Collect(collectAmt);

        // Assert: after a successful Collect, MinSum must still equal its initial value
        assertTrue(c.MinSum() == expectedMinSum);
    }
}
